package com.truthguard.dto.resolution;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import com.fasterxml.jackson.databind.annotation.JsonNaming;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * Represents an individual atomic claim generated by the Synthesizer Agent.
 */
@JsonIgnoreProperties(ignoreUnknown = true)
@JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
public class AtomicClaimDto {

    private String claimId;
    private String text;
    private ClaimType claimType = ClaimType.FACT;
    private List<UUID> citedChunkIds = new ArrayList<>();
    private List<UUID> validChunkIds = new ArrayList<>();
    private List<String> invalidChunkIds = new ArrayList<>();
    private boolean isGrounded;
    private String unsupportedReason;

    public AtomicClaimDto() {
    }

    public AtomicClaimDto(String claimId, String text, ClaimType claimType, List<UUID> citedChunkIds) {
        this.claimId = claimId;
        this.text = text;
        this.claimType = claimType;
        this.citedChunkIds = citedChunkIds != null ? citedChunkIds : new ArrayList<>();
    }

    public String getClaimId() {
        return claimId;
    }

    public void setClaimId(String claimId) {
        this.claimId = claimId;
    }

    public String getText() {
        return text;
    }

    public void setText(String text) {
        this.text = text;
    }

    public ClaimType getClaimType() {
        return claimType;
    }

    public void setClaimType(ClaimType claimType) {
        this.claimType = claimType;
    }

    public List<UUID> getCitedChunkIds() {
        return citedChunkIds;
    }

    public void setCitedChunkIds(List<UUID> citedChunkIds) {
        this.citedChunkIds = citedChunkIds != null ? citedChunkIds : new ArrayList<>();
    }

    public List<UUID> getValidChunkIds() {
        return validChunkIds;
    }

    public void setValidChunkIds(List<UUID> validChunkIds) {
        this.validChunkIds = validChunkIds != null ? validChunkIds : new ArrayList<>();
    }

    public List<String> getInvalidChunkIds() {
        return invalidChunkIds;
    }

    public void setInvalidChunkIds(List<String> invalidChunkIds) {
        this.invalidChunkIds = invalidChunkIds != null ? invalidChunkIds : new ArrayList<>();
    }

    public boolean isGrounded() {
        return isGrounded;
    }

    public void setGrounded(boolean grounded) {
        isGrounded = grounded;
    }

    public String getUnsupportedReason() {
        return unsupportedReason;
    }

    public void setUnsupportedReason(String unsupportedReason) {
        this.unsupportedReason = unsupportedReason;
    }
}
